using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using InventoryService.Services;namespace InventoryService.Controllers;[ApiController][Route("api/products")]public class ProductsController(IInventory s):ControllerBase{[Authorize(Roles="ADMIN")][HttpPost]public async Task<IActionResult>Create(string productName,int stockQty,CancellationToken c)=>Ok(await s.Save(productName,stockQty,c));[AllowAnonymous][HttpGet]public async Task<IActionResult>All(int pageNumber=1,int pageSize=10,CancellationToken c=default)=>Ok(await s.All(Math.Max(1,pageNumber),Math.Clamp(pageSize,1,100),c));[AllowAnonymous][HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken c){var p=await s.Get(id,c);return p==null?NotFound():Ok(p);}[Authorize(Roles="ADMIN")][HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,string productName,int stockQty,CancellationToken c)=>((await s.Update(id,productName,stockQty,c)) is var p&&p!=null)?Ok(p):NotFound();[Authorize(Roles="ADMIN")][HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken c)=>await s.Delete(id,c)?NoContent():NotFound();[Authorize][HttpPost("{id:guid}/reduce_stock")]public async Task<IActionResult>Reduce(Guid id,int quantity,CancellationToken c)=>Ok(new{ProductId=id,StockQty=await s.Reduce(id,quantity,c)});[Authorize][HttpPost("{id:guid}/restore_stock")]public async Task<IActionResult>Restore(Guid id,int quantity,CancellationToken c)=>Ok(new{ProductId=id,StockQty=await s.Restore(id,quantity,c)});}